def transform(grid):
    out = [row[:] for row in grid]
    points = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v in (1, 2):
                points[v] = (r, c)

    r, c = points[1]
    tr, tc = points[2]
    dr = 1 if tr > r else -1
    dc = 1 if tc > c else -1

    # Advance diagonally until one step short of the target along an axis.
    diagonal = min(abs(tr - r) - 1, abs(tc - c) - 1)
    for _ in range(diagonal):
        r += dr
        c += dc
        out[r][c] = 3

    # Complete the approach along the remaining axis, stopping adjacent to 2.
    while r != tr - dr:
        r += dr
        out[r][c] = 3
    while c != tc - dc:
        c += dc
        out[r][c] = 3

    return out
